<script setup>
import {computed,onMounted,ref,watch} from 'vue';
import {commerceRequest} from './commerce-api';
const props=defineProps({endpoint:String,token:String,connected:Boolean,products:Array});
const projects=ref([]),busy=ref(false),error=ref(''),message=ref(''),step=ref(0),project=ref(null),savedAddress=ref(null),remember=ref(true);
const emptyAddress=()=>({name:'',email:'',phone:'',address1:'',address2:'',city:'',region:'',zip:'',country:'US'});
const delivery=ref(emptyAddress());
const stages=['Your project','Board files','Assembly & extras','Shipping & review'];
const slots=[{id:'gerber',title:'Board manufacturing ZIP',accept:'.zip',help:'From your PCB design app: export Gerbers + drill files into one ZIP. Include copper, outline, solder mask, silkscreen and solder paste layers.'},{id:'bom',title:'Parts list (BOM)',accept:'.csv,.xls,.xlsx',help:'The shopping list: reference (R1, U1…), quantity, part number, manufacturer and package. Use the exact parts you want fitted.'},{id:'placement',title:'Component positions',accept:'.csv,.txt,.pos,.xls,.xlsx,.zip',help:'Also called pick-and-place, CPL, centroid or position file. Export reference, X/Y in millimetres, rotation and top/bottom side.'},{id:'drawing',title:'Assembly drawing / instructions',accept:'.pdf,.txt,.zip,.png,.jpg,.jpeg',help:'Optional: show part locations and polarity, anything not fitted, and a photo or 3D view.'},{id:'firmware',title:'Firmware / test files',accept:'.bin,.hex,.uf2,.zip,.pdf,.txt',help:'Optional: firmware to flash, programming instructions and checks to run before dispatch.'},{id:'enclosure',title:'Enclosure / box build',accept:'.step,.stp,.stl,.zip,.pdf',help:'Optional: case files and instructions if you want the finished product assembled into a housing.'}];
const assemblyRequired=computed(()=>project.value?.build==='assembled');
const addressComplete=computed(()=>['name','email','address1','city','zip','country'].every(k=>delivery.value[k]?.trim()));
const physicalProducts=computed(()=>props.products?.filter(p=>p.type==='physical') || []);
const size=n=>n>=1048576?(n/1048576).toFixed(1)+' MB':Math.ceil(n/1024)+' KB';
const request=(path,body)=>commerceRequest(props.endpoint,'/admin/pcb'+path,props.token,body);
function fresh(){project.value={name:'',revision:'1',productId:'',quantity:5,build:'assembled',assemblyType:'mixed',componentSupply:'turnkey',widthMm:null,heightMm:null,thicknessMm:1.6,layers:2,shipMode:'prototype',notes:'',shippingNotes:'',files:{},missing:[],ready:false};delivery.value={...emptyAddress(),...savedAddress.value};step.value=0;error.value='';message.value='';}
function open(id){const p=projects.value.find(p=>p.id===id);if(!p)return fresh();project.value=JSON.parse(JSON.stringify(p));delivery.value={...emptyAddress(),...(p.prototypeAddress || savedAddress.value)};step.value=0;error.value='';message.value='';}
async function run(fn){busy.value=true;error.value='';message.value='';try{await fn();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function load(){const data=await request('/projects');projects.value=data.projects;savedAddress.value=data.prototypeAddress;if(!project.value)fresh();}
async function save(){if(!project.value.name.trim())throw new Error('Start with a project name.');const body={...project.value,prototypeAddress:project.value.shipMode==='prototype'&&addressComplete.value?delivery.value:null};project.value=await request('/projects'+(project.value.id?'/'+project.value.id:''),body);const i=projects.value.findIndex(p=>p.id===project.value.id);if(i<0)projects.value.unshift(project.value);else projects.value[i]=project.value;}
function next(){return run(async()=>{await save();step.value=Math.min(3,step.value+1);});}
function saveDraft(){return run(async()=>{await save();message.value='Saved privately. You can come back to this project anytime.';});}
function upload(slot,event){const file=event.target.files?.[0];event.target.value='';if(!file)return;return run(async()=>{if(file.size>20*1024*1024)throw new Error('Choose a file smaller than 20 MB.');await save();const response=await fetch(props.endpoint.replace(/\/$/,'')+'/admin/pcb/projects/'+project.value.id+'/files/'+slot+'?name='+encodeURIComponent(file.name),{method:'POST',headers:{authorization:'Bearer '+props.token,'content-type':'application/octet-stream'},body:file});const data=await response.json();if(!response.ok)throw new Error(data.error || 'Upload failed.');project.value=data;const i=projects.value.findIndex(p=>p.id===data.id);projects.value[i]=data;message.value='File uploaded ✓';});}
function finish(){return run(async()=>{await save();if(project.value.shipMode==='prototype'&&remember.value&&addressComplete.value){await request('/prototype-address',delivery.value);savedAddress.value={...delivery.value};}message.value=project.value.ready?'Package ready for engineering review ✓':'Draft saved. The checklist shows what is still needed.';});}
function download(){return run(async()=>{await save();const response=await fetch(props.endpoint.replace(/\/$/,'')+'/admin/pcb/projects/'+project.value.id+'/export',{method:'POST',headers:{authorization:'Bearer '+props.token,'content-type':'application/json'},body:'{}'});if(!response.ok)throw new Error((await response.json()).error || 'Download failed.');const url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download='RODDY-PCB-'+project.value.id+'.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}
watch(()=>props.connected,connected=>{if(connected)run(load);else{projects.value=[];project.value=null;delivery.value=emptyAddress();}});
onMounted(()=>{if(props.connected)run(load);});
</script>
<template>
<section class="pcb-wizard">
 <header class="pcb-heading"><div><p class="eyebrow">RODDY / BUILD DESK</p><h2>FROM IDEA TO BOARD<span>.</span></h2><p>A simple file wizard for your electronic projects.</p></div><span class="pcb-private">PRIVATE PROJECT FILES</span></header>
 <p v-if="!connected" class="notice">Connect your admin account to save and upload project files.</p>
 <template v-else-if="project">
 <div class="pcb-project-switch"><label>Open a saved project<select :value="project.id || ''" :disabled="busy" @change="open($event.target.value)"><option value="">New project</option><option v-for="p in projects" :key="p.id" :value="p.id">{{p.name}} · {{p.revision}} · {{p.status}}</option></select></label><button type="button" class="button small" :disabled="busy" @click="fresh">New project +</button></div>
 <ol class="pcb-progress" aria-label="Project steps"><li v-for="(name,i) in stages" :key="name" :class="{current:step===i,complete:step>i}"><span>{{step>i?'✓':i+1}}</span>{{name}}</li></ol>
 <p v-if="error" role="alert" class="notice form-error">{{error}}</p><p v-if="message" role="status" class="notice">{{message}}</p>
 <form @submit.prevent="step===3?finish():next()">
 <div v-if="step===0" class="pcb-step"><p class="eyebrow">01 / START HERE</p><h3>What are we building?</h3><div class="form-grid"><label>Project name<input v-model="project.name" maxlength="120" placeholder="Link Commander board" required /></label><label>Revision<input v-model="project.revision" maxlength="40" required /></label><label>Link to a store product <small>optional</small><select v-model="project.productId"><option value="">Not linked yet</option><option v-for="p in physicalProducts" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>Number of boards<input v-model.number="project.quantity" type="number" min="1" max="10000" required /></label></div>
 <fieldset class="pcb-options"><legend>Who assembles the components?</legend><label :class="{selected:project.build==='diy'}"><input v-model="project.build" type="radio" value="diy" /> <strong>I’ll assemble it myself</strong><small>Make the bare boards. I’ll solder the parts and test them.</small></label><label :class="{selected:project.build==='assembled'}"><input v-model="project.build" type="radio" value="assembled" /> <strong>Factory assembles it</strong><small>Make the boards and fit the components using my files.</small></label></fieldset>
 <div v-if="assemblyRequired" class="form-grid"><label>Component style<select v-model="project.assemblyType"><option value="mixed">Mix of surface-mount and through-hole</option><option value="smt">Surface-mount (tiny parts on the surface)</option><option value="tht">Through-hole only (legs through holes)</option></select></label><label>Who supplies the parts?<select v-model="project.componentSupply"><option value="turnkey">Factory sources all parts</option><option value="partial">I supply some parts</option><option value="consigned">I supply all parts</option></select></label></div>
 <details class="pcb-optional"><summary>Board specifications <small>optional if you’re unsure</small></summary><div class="form-grid"><label>Width · mm<input v-model.number="project.widthMm" type="number" min="0.1" max="1000" step="any" @change="project.widthMm=project.widthMm || null" /></label><label>Height · mm<input v-model.number="project.heightMm" type="number" min="0.1" max="1000" step="any" @change="project.heightMm=project.heightMm || null" /></label><label>Copper layers<input v-model.number="project.layers" type="number" min="1" max="32" /></label><label>Thickness · mm<input v-model.number="project.thicknessMm" type="number" min="0.1" max="10" step="0.1" /></label></div><p>Leave dimensions blank if you don’t know. They still need checking against the design before a quote.</p></details></div>
 <div v-if="step===1 || step===2" class="pcb-step"><p class="eyebrow">{{step===1?'02 / THE BOARD':'03 / THE FINISHING TOUCHES'}}</p><h3>{{step===1?'Upload your board ZIP.':'Parts, positions and extras.'}}</h3><p v-if="step===2&&!assemblyRequired">You’re assembling this yourself, so everything here is optional. Keep useful reference files with the project.</p><p v-else-if="step===2">For factory assembly, add the parts list and positions. Through-hole-only boards don’t need a positions file.</p>
 <article v-for="slot in slots.filter(s=>step===1?s.id==='gerber':s.id!=='gerber')" :key="slot.id" class="pcb-upload"><div><h4>{{slot.title}} <small>{{slot.id==='gerber' || (assemblyRequired && (slot.id==='bom' || (slot.id==='placement' && project.assemblyType!=='tht')))?'Required':'Optional'}}</small></h4><p>{{slot.help}}</p><p v-if="project.files[slot.id]" class="pcb-file">✓ {{project.files[slot.id].name}} <span>{{size(project.files[slot.id].size)}}</span></p></div><label class="button small">{{busy?'Working…':project.files[slot.id]?'Replace file ↑':'Choose file ↑'}}<input type="file" :aria-label="slot.title" :accept="slot.accept" :disabled="busy" @change="upload(slot.id,$event)" /></label></article><p class="help-copy">Up to 20 MB per file. Files stay in your private project storage.</p></div>
 <div v-if="step===3" class="pcb-step"><p class="eyebrow">04 / WHERE DOES IT GO?</p><h3>Prototypes for you, or boards for buyers.</h3><fieldset class="pcb-options"><legend>Shipping destination</legend><label :class="{selected:project.shipMode==='prototype'}"><input v-model="project.shipMode" type="radio" value="prototype" /><strong>Ship prototypes to me</strong><small>Use my saved address for samples and testing.</small></label><label :class="{selected:project.shipMode==='customer'}"><input v-model="project.shipMode" type="radio" value="customer" /><strong>Ship to the customer</strong><small>Prepare this project for a future paid-order delivery address.</small></label></fieldset>
 <div v-if="project.shipMode==='prototype'" class="pcb-address"><h4>Your prototype delivery address</h4><div class="form-grid"><label>Recipient name<input v-model="delivery.name" maxlength="150" /></label><label>Email<input v-model="delivery.email" type="email" maxlength="254" /></label><label>Phone<input v-model="delivery.phone" type="tel" maxlength="150" /></label><label>Country code<input v-model="delivery.country" maxlength="2" placeholder="US, CA or PH" @input="delivery.country=delivery.country.toUpperCase()" /></label><label class="full">Street address<input v-model="delivery.address1" maxlength="150" /></label><label class="full">Apartment / suite<input v-model="delivery.address2" maxlength="150" /></label><label>City<input v-model="delivery.city" maxlength="150" /></label><label>State / province<input v-model="delivery.region" maxlength="150" /></label><label>Postal code<input v-model="delivery.zip" maxlength="150" /></label></div><label class="check"><input v-model="remember" type="checkbox" />Remember my prototype address privately</label></div>
 <div class="form-grid"><label class="full">Assembly / testing notes<textarea v-model="project.notes" rows="3" maxlength="4000" placeholder="Anything to fit, leave out, flash or test…" /></label><label class="full">Packaging / shipping notes<textarea v-model="project.shippingNotes" rows="3" maxlength="2000" placeholder="RODDY packaging, neutral packing slip, ESD bag…" /></label></div>
 <div class="pcb-review"><h4>Package checklist</h4><p><b>{{project.name}}</b> · {{project.revision}} · {{project.quantity}} boards</p><p>{{assemblyRequired?'Factory assembly':'DIY assembly / bare boards'}} · {{project.shipMode==='prototype'?'Prototypes to you':'Customer delivery template'}}</p><ul><li v-for="s in slots.filter(s=>s.id==='gerber' || project.files[s.id] || (assemblyRequired && (s.id==='bom' || (s.id==='placement' && project.assemblyType!=='tht'))))" :key="s.id">{{project.files[s.id]?'✓':'○'}} {{s.title}}<span>{{project.files[s.id]?.name || 'Still needed'}}</span></li><li v-if="project.shipMode==='prototype'">{{addressComplete?'✓':'○'}} Prototype address<span>{{addressComplete?delivery.name:'Still needed'}}</span></li></ul></div>
 <p class="pcb-api-note">PCBWay API preparation: your files, build choices and delivery plan are packaged together. Uploading and saving stay private; supplier submission, payment, assembly and dispatch are not connected yet.</p><a class="text-button" href="https://www.pcbway.com/assembly-file-requirements.html" target="_blank" rel="noopener noreferrer">File guide ↗</a></div>
 <footer class="pcb-actions"><button v-if="step>0" type="button" class="button small" :disabled="busy" @click="step--">← Back</button><button type="button" class="text-button" :disabled="busy" @click="saveDraft">Save draft</button><button class="button primary" :disabled="busy">{{busy?'Working…':step===3?'Save project ✓':'Next step →'}}</button><button v-if="step===3" type="button" class="button small" :disabled="busy || !project.id" @click="download">Download private package ↓</button></footer>
 </form>
 </template>
</section>
</template>
<style scoped>
.pcb-heading{display:flex;justify-content:space-between;gap:20px;align-items:center;flex-wrap:wrap;margin-bottom:28px}.pcb-heading h2{font-size:clamp(28px,4vw,46px);font-weight:900;margin:12px 0}.pcb-heading h2 span{color:#f37727}.pcb-heading p:last-child{font-size:14px;opacity:.7}.pcb-private{font:10px monospace;padding:10px;border:1px solid #668f78;color:#9bc8ab}.pcb-project-switch{display:flex;gap:16px;align-items:end;margin:24px 0}.pcb-project-switch label{display:grid;gap:8px;font-size:12px;flex:1}.pcb-project-switch select{padding:10px;border:1px solid var(--color-border,#444);background:transparent}.pcb-progress{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));padding:0;margin:28px 0;gap:12px;list-style:none}.pcb-progress li{font-size:12px;display:flex;gap:9px;align-items:center;opacity:.5;border-bottom:2px solid #555;padding-bottom:14px}.pcb-progress span{display:inline-grid;place-items:center;width:26px;height:26px;border:1px solid currentColor;border-radius:50%;flex-shrink:0}.pcb-progress .current{opacity:1;border-color:#f37727}.pcb-progress .complete{opacity:1;border-color:#9bc8ab;color:#9bc8ab}.pcb-step{border:1px solid var(--color-border,#444);padding:28px}.pcb-step h3{font-size:27px;font-weight:800;margin:12px 0 20px}.pcb-step p{font-size:13px;line-height:1.8}.pcb-options{margin:24px 0;display:grid;grid-template-columns:1fr 1fr;gap:14px}.pcb-options legend{font-size:12px;margin-bottom:12px}.pcb-options label{border:1px solid var(--color-border,#444);padding:18px;cursor:pointer}.pcb-options label.selected{border-color:#93b0db;background:#93b0db0c}.pcb-options strong{font-size:14px;display:inline;margin-left:8px}.pcb-options small{display:block;font-size:12px;line-height:1.7;opacity:.7;margin-top:9px}.pcb-optional{border-top:1px solid var(--color-border,#444);padding-top:20px;margin-top:24px}.pcb-optional summary{cursor:pointer;font-size:13px;margin-bottom:18px}.pcb-optional small{font-size:11px;opacity:.7}.pcb-upload{display:flex;align-items:start;gap:20px;justify-content:space-between;border:1px solid var(--color-border,#444);padding:20px;margin:16px 0}.pcb-upload h4{font-size:15px;font-weight:700;margin-bottom:7px}.pcb-upload h4 small{font:10px monospace;margin-left:10px;opacity:.65}.pcb-upload p{font-size:12px;max-width:640px}.pcb-upload input{position:absolute;clip-path:inset(50%);width:1px;height:1px;overflow:hidden}.pcb-upload>label{cursor:pointer;white-space:nowrap}.pcb-upload>label:focus-within{outline:2px solid #93b0db}.pcb-file{color:#9bc8ab;overflow-wrap:anywhere;margin-top:12px}.pcb-file span{margin-left:10px;opacity:.7;font:10px monospace}.pcb-address{padding:22px;border:1px solid var(--color-border,#444);margin:20px 0}.pcb-address h4{font-size:16px;font-weight:700;margin-bottom:20px}.pcb-review{padding:22px;border-top:3px solid #93b0db;background:#93b0db0c;margin:24px 0}.pcb-review h4{font-size:17px;font-weight:700;margin-bottom:12px}.pcb-review ul{list-style:none;padding:0;margin:14px 0 0}.pcb-review li{display:flex;justify-content:space-between;gap:12px;font-size:12px;border-top:1px solid var(--color-border,#444);padding:12px 0}.pcb-review li span{opacity:.65;overflow-wrap:anywhere;text-align:right}.pcb-api-note{font-size:12px!important;opacity:.7}.pcb-actions{display:flex;align-items:center;gap:16px;flex-wrap:wrap;padding:24px 0}.pcb-address .check{font-size:12px;margin-top:16px}@media(max-width:650px){.pcb-progress{grid-template-columns:1fr 1fr}.pcb-step{padding:18px}.pcb-options{grid-template-columns:1fr}.pcb-upload{display:block}.pcb-upload>label{display:inline-flex;margin-top:16px}.pcb-project-switch{align-items:start;flex-direction:column}.pcb-project-switch label{width:100%}.pcb-review li{display:block}.pcb-review li span{display:block;text-align:left;margin-top:5px}}
</style>
